{# 卡簧槽程序模板 #}

{% for z_pos in z_offsets %}
; --- 卡簧槽 Z={{ z_pos | v3_signed(3) }} ---
G0 Z{{ z_pos | v3_fixed(3) }}
G0 X{{ (X_RAW_D + 10) | v3_fixed(3) }}
M4=97
R12={{ X_TIP_D | v3_fixed(3) }}
R13={{ z_pos | v3_fixed(3) }}
R14={{ WIDTH_CIRCLIP | v3_fixed(3) }}
R15={{ (X_TIP_D - X_DOWN_D) | v3_fixed(3) }}/2
R16=0.000
R17=0.000
R18={{ MAX_CUTDIPTH | v3_fixed(3) }}
R19={{ WIDTH_CUTER | v3_fixed(3) }}
R20={{ FEEDRATE | v3_fixed(3) }}
R21=0.300
DB_CYCLE93(R12,R13,R14,R15,R16,R17,R18,R19,R20,R21)
G0 X{{ (X_RAW_D + 10) | v3_fixed(3) }}
STOPRE
{% endfor %}

{# NAME: 12-闭口-非圆头键槽-粗铣(深度1刀/宽度3刀/刀具半径<圆角半径) #}
;----粗铣键槽子程序----
GX73
GZ73 Y0
L184(0,0,,,,0)
L171("{{ U_RT }}")
L172(0)
L171("{{ U_RTB }}")
GX73
GZ73 Y0
L184(0,90,,,,0)
L140(0.00,4,0)
SETMS(1)
DIAMOF
G17
G90
D1
;''''基础坐标系偏移''''
XMW_1=0 YMW_1=0 ZMW_1=I_R9[35]+I_R9{{ U_ID }} CMW_1=0
G59 X=XMW_1 Y=YMW_1 Z=ZMW_1 C=CMW_1
;''''旋转-定位键槽''''
AROT Y90
AROT Z180
ATRANS X{{ (U_Z) | v3_fixed(3) }} Z{{ (U_D/2) | v3_fixed(3) }}
;''''起转-给水''''
G97 S1={{ (U_RTRPM) | v3_fixed(0) }} M1=3
M13=8 M10=150 H50=80
;-----------
;''''刀具定位''''
G94 G40 G0 X{{ (U_Q-U_ALBR-U_RTD-(U_RC+2)/(U_ANG | tan_d)) | v3_fixed(3) }} Y0 C=DC(0.00)
G0 Z10
G1 Z2 F400
;''''{{ (U_ANG) | v3_fixed(0) }}°入刀''''
G1 X{{ (U_Q-U_ALBR-U_RTD) | v3_fixed(3) }} Z{{ (-U_RC) | v3_fixed(1) }} F200
;''''粗铣''''
G1 G41 X{{ (-(U_A+U_Q-U_ALBR)) | v3_fixed(3) }} F{{ (U_RTRF) | v3_fixed(0) }}
G1 Y{{ (-(U_B/2-U_Q)) | v3_fixed(3) }} F{{ (U_RTRF/2) | v3_fixed(0) }}
G3 X{{ (-U_A) | v3_fixed(3) }} Y{{ (-(U_B/2-U_ALBR)) | v3_fixed(3) }} I={{ (U_Q-U_ALBR) | v3_fixed(3) }}
G1 X{{ (-U_Q) | v3_fixed(3) }} F{{ (U_RTRF) | v3_fixed(0) }}
G1 X0 F{{ (U_RTRF/2) | v3_fixed(0) }}
G3 X{{ (U_Q-U_ALBR) | v3_fixed(3) }} Y{{ (-(U_B/2-U_Q)) | v3_fixed(3) }} J={{ (U_Q-U_ALBR) | v3_fixed(3) }}
G1 Y{{ (U_B/2-U_Q) | v3_fixed(3) }}
G3 X0 Y{{ (U_B/2-U_ALBR) | v3_fixed(3) }} I={{ (-(U_Q-U_ALBR)) | v3_fixed(3) }}
G1 X{{ (-(U_A-U_Q)) | v3_fixed(3) }} F{{ (U_RTRF) | v3_fixed(0) }}
G1 X{{ (-U_A) | v3_fixed(3) }} F{{ (U_RTRF/2) | v3_fixed(0) }}
G3 X{{ (-(U_A+U_Q-U_ALBR)) | v3_fixed(3) }} Y{{ (U_B/2-U_Q) | v3_fixed(3) }} J={{ (-(U_Q-U_ALBR)) | v3_fixed(3) }}
;''''半精铣''''
G1 X{{ (-(U_A+U_Q-U_ALBHF)) | v3_fixed(3) }} Y{{ (-(U_B/2-U_Q)) | v3_fixed(3) }} F{{ (U_RTFF/2) | v3_fixed(0) }}
G1 Z{{ (-U_C) | v3_fixed(3) }} F60
G3 X{{ (-U_A) | v3_fixed(3) }} Y{{ (-(U_B/2-U_ALBHF)) | v3_fixed(3) }} I={{ (U_Q-U_ALBHF) | v3_fixed(3) }} F{{ (U_RTFF/2) | v3_fixed(0) }}
G1 X{{ (-U_Q) | v3_fixed(3) }} F{{ (U_RTFF) | v3_fixed(0) }}
G1 X0 F{{ (U_RTFF/2) | v3_fixed(0) }}
G3 X{{ (U_Q-U_ALBHF) | v3_fixed(3) }} Y{{ (-(U_B/2-U_Q)) | v3_fixed(3) }} J={{ (U_Q-U_ALBHF) | v3_fixed(3) }}
G1 Y{{ (U_B/2-U_Q) | v3_fixed(3) }}
G3 X0 Y{{ (U_B/2-U_ALBHF) | v3_fixed(3) }} I={{ (-(U_Q-U_ALBHF)) | v3_fixed(3) }}
G1 X{{ (-(U_A-U_Q)) | v3_fixed(3) }} F{{ (U_RTFF) | v3_fixed(0) }}
G1 X{{ (-U_A) | v3_fixed(3) }} F{{ (U_RTFF/2) | v3_fixed(0) }}
G3 X{{ (-(U_A+U_Q-U_ALBHF)) | v3_fixed(3) }} Y{{ (U_B/2-U_Q) | v3_fixed(3) }} J={{ (-(U_Q-U_ALBHF)) | v3_fixed(3) }}
G1 Y{{ (-(U_B/2-U_Q)) | v3_fixed(3) }}
G3 X{{ (-U_A) | v3_fixed(3) }} Y{{ (-(U_B/2-U_ALBHF)) | v3_fixed(3) }} I={{ (U_Q-U_ALBHF) | v3_fixed(3) }}
G1 G40 Y0
G1 X{{ (U_Q-U_ALBHF-U_RTD) | v3_fixed(3) }} F{{ (U_RTFF) | v3_fixed(0) }}
G1 Z2
G0 Z100
;-----------
ROT
TRANS
DIAMON
M14=9
M13=9
M10=151
M1=5
GX73
GZ73 Y0
M01
;-----------
RET


;........

