{# NAME: 统一精铣键槽模板 (keyway_finish.j2) #}
{# 支持: 闭口非圆头/闭口圆头/左开口/右开口, 一次走刀到最终尺寸 #}
{# 切削参数由core层计算后传入: finish_n, finish_vf #}
{# 走刀路径决策由core层计算后传入: path_type (closed_non_round/closed_round/right_open/left_open) #}

;----精铣键槽子程序----
{% include 'v3-keyway-keyway-header' %}

{# ---- 刀具定位 ---- #}
{% if path_type in ['closed_non_round', 'closed_round'] %}
    G94 G40 G0 X0 Y0 C=DC(0.00)
{% else %}
    G94 G40 G0 X={{ (U_FTD / 2 + 5) | v3_fixed(3) }} Y0 C=DC(0.00)
{% endif %}
G0 Z10

{# ---- 入刀 (Z向分两段: 快进+慢进) ---- #}
G1 Z={{ (-(U_C - 5)) | v3_fixed(3) }} F3000
G1 Z={{ (-U_C) | v3_fixed(3) }} F100

{# ========== 精铣轮廓 ========== #}
{% if path_type == 'closed_non_round' %}
    {# ---- 闭口非圆头 ---- #}
    G1 G41 Y={{ (U_B / 2) | v3_fixed(3) }} F={{ (finish_vf) | v3_fixed(0) }}
    G1 X={{ (-U_A) | v3_fixed(3) }}
    G3 X={{ (-(U_A + U_Q)) | v3_fixed(3) }} Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} J={{ (-U_Q) | v3_fixed(3) }}
    G1 Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }}
    G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-U_B / 2) | v3_fixed(3) }} I={{ (U_Q) | v3_fixed(3) }}
    G1 X0
    G3 X={{ (U_Q) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }} J={{ (U_Q) | v3_fixed(3) }}
    G1 Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }}
    G3 X0 Y={{ (U_B / 2) | v3_fixed(3) }} I={{ (-U_Q) | v3_fixed(3) }}
    G1 G40 Y0 Z2

{% elif path_type == 'closed_round' %}
    {# ---- 闭口圆头 (两端整圆, 半径=U_B/2) ---- #}
    G1 G41 Y={{ (U_B / 2) | v3_fixed(3) }} F={{ (finish_vf) | v3_fixed(0) }}
    G1 X={{ (-U_A) | v3_fixed(3) }}
    G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-U_B / 2) | v3_fixed(3) }} J={{ (-U_B / 2) | v3_fixed(3) }}
    G1 X0
    G3 X0 Y={{ (U_B / 2) | v3_fixed(3) }} J={{ (U_B / 2) | v3_fixed(3) }}
    G1 G40 Y0 Z2

{% elif path_type == 'right_open' %}
    {# ---- 右开口非圆头 ---- #}
    G1 G41 Y={{ (U_B / 2) | v3_fixed(3) }} F={{ (finish_vf) | v3_fixed(0) }}
    G1 X={{ (-U_A) | v3_fixed(3) }}
    G3 X={{ (-(U_A + U_Q)) | v3_fixed(3) }} Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} J={{ (-U_Q) | v3_fixed(3) }}
    G1 Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }}
    G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-U_B / 2) | v3_fixed(3) }} I={{ (U_Q) | v3_fixed(3) }}
    G1 X={{ (U_FTD / 2 + 5) | v3_fixed(3) }}
    G1 G40 Y0 Z2

{% elif path_type == 'left_open' %}
    {# ---- 左开口非圆头 (坐标系已旋转180°) ---- #}
    G1 G41 Y={{ (U_B / 2) | v3_fixed(3) }} F={{ (finish_vf) | v3_fixed(0) }}
    G1 X={{ (-U_A) | v3_fixed(3) }}
    G3 X={{ (-(U_A + U_Q)) | v3_fixed(3) }} Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} J={{ (-U_Q) | v3_fixed(3) }}
    G1 Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }}
    G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-U_B / 2) | v3_fixed(3) }} I={{ (U_Q) | v3_fixed(3) }}
    G1 X={{ (U_FTD / 2 + 5) | v3_fixed(3) }}
    G1 G40 Y0 Z2
{% endif %}

{% include 'v3-keyway-keyway-footer' %}

{# NAME: 统一粗铣键槽模板 (keyway_rough.j2) #}
{# 支持: 闭口非圆头/闭口圆头/左开口/右开口, 任意深度分层, 宽度2刀/3刀 #}
{# 切削参数由core层计算后传入: rough_n, rough_vf, rough_vf_corner, semi_vf #}
{# 分层信息由core层计算后传入: layer_count, depths (列表), is_last_layer 由循环判断 #}
{# 走刀路径决策由core层计算后传入: path_type (closed_2pass/closed_3pass/round_2pass/right_open/left_open) #}

;----粗铣键槽子程序----
{% include 'v3-keyway-keyway-header' %}

{# ========== 逐层加工 ========== #}
{% for layer_idx in range(layer_count) %}
    {% set depth = target_depths[layer_idx] %}
    {% set pass_depth = depths[layer_idx] %}
    {% set is_last = (layer_idx == layer_count - 1) %}

    {# ---- 刀具定位 ---- #}
    {% if path_type in ['closed_2pass', 'closed_3pass', 'round_2pass'] %}
        {# 闭口键槽: 斜向入刀起点 #}
        {% set ramp_x_start = U_Q - U_ALBR - U_RTD - (depth + 2) / (U_ANG | tan_d) %}
        {% set ramp_x_end = U_Q - U_ALBR - U_RTD %}
        G94 G40 G0 X={{ (ramp_x_start) | v3_fixed(3) }} Y0 C=DC(0.00)
    {% else %}
        {# 开口键槽: 开口外侧定位 #}
        G94 G40 G0 X={{ (U_RTD / 2 + 5) | v3_fixed(3) }} Y0 C=DC(0.00)
    {% endif %}
    G0 Z10
    G1 Z2 F400

    {# ---- 入刀 ---- #}
    {% if path_type in ['closed_2pass', 'closed_3pass', 'round_2pass'] %}
        ; {{ (U_ANG) | v3_fixed(0) }}°斜向入刀 (第{{ layer_idx + 1 }}层, 切深{{ (pass_depth) | v3_fixed(2) }})
        G1 X={{ (ramp_x_end) | v3_fixed(3) }} Z={{ (-depth) | v3_fixed(3) }} F200
    {% else %}
        ; 开口端垂直入刀 (第{{ layer_idx + 1 }}层, 切深{{ (pass_depth) | v3_fixed(2) }})
        G1 Z={{ (-depth) | v3_fixed(3) }} F200
    {% endif %}

    {# ========== 走刀轮廓 (按path_type分支) ========== #}

    {% if path_type == 'closed_2pass' %}
        {# ---- 闭口非圆头 - 宽度2刀 (刀具半径≈圆角半径) ---- #}
        G1 G41 X={{ (U_Q - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (-(U_A + U_Q - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 Y={{ (-(U_B / 2 - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (-U_Q) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (U_Q - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}

    {% elif path_type == 'closed_3pass' %}
        {# ---- 闭口非圆头 - 宽度3刀 (刀具半径<圆角半径, 含G3圆弧) ---- #}
        G1 G41 X={{ (-(U_A + U_Q - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_ALBR)) | v3_fixed(3) }} I={{ (U_Q - U_ALBR) | v3_fixed(3) }}
        G1 X={{ (-U_Q) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X0 F={{ (rough_vf_corner) | v3_fixed(0) }}
        G3 X={{ (U_Q - U_ALBR) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }} J={{ (U_Q - U_ALBR) | v3_fixed(3) }}
        G1 Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G3 X0 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} I={{ (-(U_Q - U_ALBR)) | v3_fixed(3) }}
        G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (-U_A) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G3 X={{ (-(U_A + U_Q - U_ALBR)) | v3_fixed(3) }} Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} J={{ (-(U_Q - U_ALBR)) | v3_fixed(3) }}

    {% elif path_type == 'round_2pass' %}
        {# ---- 闭口圆头 - 宽度2刀 (两端整圆G3, 半径=U_B/2) ---- #}
        G1 G41 X={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G3 X0 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} I={{ (-U_B / 2 + U_ALBR) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (-(U_A - U_B / 2)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (-U_A) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_ALBR)) | v3_fixed(3) }} J={{ (-U_B / 2 + U_ALBR) | v3_fixed(3) }}
        G1 X={{ (-U_B / 2) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X0 F={{ (rough_vf_corner) | v3_fixed(0) }}
        G3 X={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} Y0 J={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }}

    {% elif path_type == 'right_open' %}
        {# ---- 右开口非圆头 - 宽度2刀 (从开口端进刀, 半闭合轮廓) ---- #}
        G1 G41 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (-(U_A + U_Q - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 Y={{ (-(U_B / 2 - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (U_RTD / 2 + 5) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}

    {% elif path_type == 'left_open' %}
        {# ---- 左开口非圆头 - 宽度2刀 (坐标系已旋转180°, 同右开口逻辑) ---- #}
        G1 G41 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (-(U_A + U_Q - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 Y={{ (-(U_B / 2 - U_ALBR)) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
        G1 X={{ (U_RTD / 2 + 5) | v3_fixed(3) }} F={{ (rough_vf_corner) | v3_fixed(0) }}
        G1 Y={{ (U_B / 2 - U_ALBR) | v3_fixed(3) }} F={{ (rough_vf) | v3_fixed(0) }}
    {% endif %}

    {# ---- 层间处理 ---- #}
    {% if is_last %}
        {# 最后一层 → 半精铣 #}
        ; 半精铣 (Z向到最终深度, 留{{ (U_ALBHF) | v3_fixed(2) }}单边余量)
        G1 Z={{ (-U_C) | v3_fixed(3) }} F60
        {% if path_type == 'closed_2pass' %}
            G1 Y={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X={{ (-(U_A + U_Q - U_ALBHF)) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 Y={{ (-(U_B / 2 - U_ALBHF)) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X={{ (-U_Q) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 X={{ (U_Q - U_ALBHF) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 Y={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 X={{ (-U_RTD / 2) | v3_fixed(3) }}
        {% elif path_type == 'closed_3pass' %}
            G1 X={{ (-(U_A + U_Q - U_ALBHF)) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_ALBHF)) | v3_fixed(3) }} I={{ (U_Q - U_ALBHF) | v3_fixed(3) }}
            G1 X={{ (-U_Q) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X0 F={{ (semi_vf / 2) | v3_fixed(0) }}
            G3 X={{ (U_Q - U_ALBHF) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_Q)) | v3_fixed(3) }} J={{ (U_Q - U_ALBHF) | v3_fixed(3) }}
            G1 Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G3 X0 Y={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} I={{ (-(U_Q - U_ALBHF)) | v3_fixed(3) }}
            G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 X={{ (-U_A) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G3 X={{ (-(U_A + U_Q - U_ALBHF)) | v3_fixed(3) }} Y={{ (U_B / 2 - U_Q) | v3_fixed(3) }} J={{ (-(U_Q - U_ALBHF)) | v3_fixed(3) }}
            G1 G40 Y0
            G1 X={{ (U_Q - U_ALBHF - U_RTD) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
        {% elif path_type == 'round_2pass' %}
            G1 X={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G3 X0 Y={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} I={{ (-U_B / 2 + U_ALBHF) | v3_fixed(3) }}
            G1 X={{ (-(U_A - U_B / 2)) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X={{ (-U_A) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G3 X={{ (-U_A) | v3_fixed(3) }} Y={{ (-(U_B / 2 - U_ALBHF)) | v3_fixed(3) }} J={{ (-U_B / 2 + U_ALBHF) | v3_fixed(3) }}
            G1 X={{ (-U_B / 2) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X0 F={{ (semi_vf / 2) | v3_fixed(0) }}
            G3 X={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} Y0 J={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }}
            G1 G40 X0 Z2
        {% else %}
            {# 开口键槽半精铣 #}
            G1 Y={{ (U_B / 2 - U_ALBHF) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 X={{ (-(U_A - U_Q)) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X={{ (-(U_A + U_Q - U_ALBHF)) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 Y={{ (-(U_B / 2 - U_ALBHF)) | v3_fixed(3) }} F={{ (semi_vf) | v3_fixed(0) }}
            G1 X={{ (U_RTD / 2 + 5) | v3_fixed(3) }} F={{ (semi_vf / 2) | v3_fixed(0) }}
            G1 G40 Y0 Z2
        {% endif %}
    {% else %}
        {# 非最后一层 → 抬刀返回起点 #}
        G1 G40 X={{ (U_Q - U_ALBR - U_RTD) | v3_fixed(3) }} Y0 Z2
    {% endif %}

{% endfor %}
{# ========== 逐层加工结束 ========== #}

