{# ==================================================== #}
{# ========== 轨迹生成区 ========== #}
;---SYT-Left--D{{ (end_x) | v3_fixed(1) }}---start---
G0 Z{{ (actual_sta_z) | v3_fixed(3) }}
G0 X{{ (actual_sta_x + 10) | v3_fixed(3) }}
WAITM({{ sync_num_start }},1,2)
{% for i in range(1, cut_num + 1) %}
{# --- 计算当前刀次的坐标 --- #}
{% set x_val_ch1 = actual_sta_x - ap_1 - (i - 1) * (ap_1 + ap_2) %}
{% set x_val_ch2 = actual_sta_x - i * (ap_1 + ap_2) %}
{% set z_base = actual_sta_z - (i-1) * (ap_1+ap_2)/(2*(25 | tan_d)) %}
{# 定义常量距离 #}
{% set dis_1 = 4.0 %}
{% set dis_2 = 8.0 %}
{# 计算各点位 #}
{% set z_start_ch1 = z_base + dis_1/2 %}
{% set z_start_ch2 = z_base + dis_2/2 %}
{% set x_target_ch1_app = x_val_ch1 + ap_1 + dis_1 %}
{% set x_target_ch2_app = x_val_ch2 + ap_1 + ap_2 + dis_2 %}
{# ------------------------ #}
{% if channel == 1 %}
G0 Z{{ (z_start_ch1) | v3_fixed(3) }}
G0 X{{ (x_target_ch1_app) | v3_fixed(3) }}
{% else %}
G0 Z{{ (z_start_ch2) | v3_fixed(3) }}
G0 X{{ (x_target_ch2_app) | v3_fixed(3) }}
{% endif %}
WAITM({{ sync_num_start + i }},1,2)
{% if channel == 1 %}
G1 Z{{ (z_base) | v3_fixed(3) }} ANG=225 F0.2
G1 X{{ (x_val_ch1) | v3_fixed(3) }} ANG=205 F0.2
{% else %}
G1 Z{{ (z_start_ch2 - dis_1/2) | v3_fixed(3) }} ANG=225 F0.2
G1 Z{{ (z_base) | v3_fixed(3) }} ANG=225 F0.2
G1 X{{ (x_val_ch2) | v3_fixed(3) }} ANG=205 F0.2
{% endif %}
G1 Z{{ (end_z) | v3_fixed(3) }} F{{ (sync_feed | nc_trim_fixed(2)) }}
G91
G1 X{{ (ap_1 + ap_2 + 4) | v3_fixed(3) }} F40
G90
{% endfor %}
G0 X{{ (actual_sta_x + 10) | v3_fixed(3) }}
G0 Z{{ (end_z) | v3_fixed(3) }}
