G0 Z{{ (Z_START) | v3_fixed(3) }}
G0 X{{ (X_START) | v3_fixed(3) }}
M4=97
G0 G41 X{{ (D1_COMP_START) | v3_fixed(3) }}
G1 X{{ (D1_CUT) | v3_fixed(3) }} ANG={{ (ANG_1) | v3_fixed(0) }} RND={{ (R) | v3_fixed(1) }} F0.2
G1 Z{{ (ES_Z) | v3_fixed(3) }} RND={{ (R) | v3_fixed(1) }}
G1 X{{ (D2_COMP_CUT) | v3_fixed(3) }}
G1 X{{ (ES_D2) | v3_fixed(3) }} ANG=45
G0 G40 X{{ (X_START) | v3_fixed(3) }}
; --------------------------------------
{% elif groove_type == "FS" and side == "Right" %}
{# FS类型右侧越程槽 #}
; --- FS_Right ({{ STD_KEY }}) ---
G0 Z{{ (Z_START) | v3_fixed(3) }}
G0 X{{ (X_START) | v3_fixed(3) }}
M4=97
G0 G42 X{{ (D1_COMP_START) | v3_fixed(3) }}
G1 X{{ (D1_CUT) | v3_fixed(3) }} ANG={{ (ANG_1) | v3_fixed(0) }} RND={{ (R) | v3_fixed(1) }} F0.2
G1 Z{{ (Z_MID) | v3_fixed(3) }} RND={{ (R) | v3_fixed(1) }}
G1 Z{{ (FS_Z_PLUS1) | v3_fixed(3) }} ANG={{ (ANG_2) | v3_fixed(0) }}
G0 G40 X{{ (X_START) | v3_fixed(3) }}
; --------------------------------------
{% elif groove_type == "FS" and side == "Left" %}
{# FS类型左侧越程槽 #}
; --- FS_Left ({{ STD_KEY }}) ---
G0 Z{{ (Z_START) | v3_fixed(3) }}
G0 X{{ (X_START) | v3_fixed(3) }}
M4=97
G0 G41 X{{ (D1_COMP_START) | v3_fixed(3) }}
G1 X{{ (D1_CUT) | v3_fixed(3) }} ANG={{ (ANG_1) | v3_fixed(0) }} RND={{ (R) | v3_fixed(1) }} F0.2
G1 Z{{ (Z_MID) | v3_fixed(3) }} RND={{ (R) | v3_fixed(1) }}
G1 Z{{ (FS_Z_MINUS1) | v3_fixed(3) }} ANG={{ (ANG_2) | v3_fixed(0) }}
G0 G40 X{{ (X_START) | v3_fixed(3) }}
; --------------------------------------
{% endif %}
{# ================================ #}
